from pathlib import Path
import json

ROOT = Path('projects/frontier-settlement')
JAVA = ROOT / 'src/main/java/kr/moonseungjun/frontiersettlement'


def read(path):
    return path.read_text(encoding='utf-8')


def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding='utf-8')


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, found {count}')
    return text.replace(old, new, 1)

# Version marker.
props_path = ROOT / 'gradle.properties'
props = read(props_path)
props = replace_once(props, 'mod_version=0.1.0-alpha.87', 'mod_version=0.1.0-alpha.88', 'version')
if '# Alpha.88 worker runtime recovery:' not in props:
    props += '\n# Alpha.88 worker runtime recovery: walkable interaction approaches, attackable workers, completion-first finalization.\n'
write(props_path, props)

# Production worker navigation: keep service authority, but path to walkable interaction positions.
worker_path = JAVA / 'settlement/SettlementWorkerService.java'
worker = read(worker_path)
worker = replace_once(
    worker,
    '''            BuildingRecord building = buildings.get(i);\n            if (!level.hasChunkAt(building.workCenter())) continue;\n            work.run(level, data, workers.get(i), building);''',
    '''            BuildingRecord building = buildings.get(i);\n            if (!level.hasChunkAt(building.workCenter())) continue;\n            FrontierWorkerEntity worker = workers.get(i);\n            // Frontier owns the work order, but workers remain ordinary damageable mobs.\n            // Clear stale Alpha.84-87 quarantine/active-project flags on every ordinary work tick.\n            worker.setNoAi(false);\n            worker.setInvulnerable(false);\n            work.run(level, data, worker, building);''',
    'ordinary worker normalization')
worker = replace_once(worker, 'workerRouteBounds(data, building.workCenter(), 24)',
                      'workerRouteBounds(data, building.workCenter(), LOCAL_RESOURCE_ROUTE_MARGIN)',
                      'resource worker lookup envelope')
for old, new, label in [
    ('move(worker, camp.workCenter(), 0.82D);', 'moveNear(level, worker, camp.workCenter(), 0.82D);', 'lumber home approach'),
    ('move(worker, target, 0.92D);', 'moveNear(level, worker, target, 0.92D);', 'lumber target approach'),
    ('move(worker, farm.workCenter(), 0.88D);', 'moveNear(level, worker, farm.workCenter(), 0.88D);', 'farm approach'),
    ('move(worker, quarry.workCenter(), 0.82D);', 'moveNear(level, worker, quarry.workCenter(), 0.82D);', 'quarry home approach'),
    ('move(worker, target, 0.90D);', 'moveNear(level, worker, target, 0.90D);', 'quarry target approach'),
    ('move(worker, work, 0.86D);', 'moveNear(level, worker, work, 0.86D);', 'mine approach'),
    ('move(worker, target, 0.85D);', 'moveNear(level, worker, target, 0.85D);', 'storage approach'),
]:
    worker = replace_once(worker, old, new, label)
worker = replace_once(
    worker,
    '''    private static void move(FrontierWorkerEntity worker, BlockPos target, double speed) {\n        worker.getNavigation().moveTo(target.getX() + 0.5D, target.getY(), target.getZ() + 0.5D, speed);\n    }''',
    '''    /**\n     * PathfinderMob has no villager POI/interaction brain to turn a solid target block into a usable\n     * standing position. Never path to a log, quarry block, barrel, or fenced work-center directly:\n     * try nearby loaded walkable cells and let vanilla ground navigation choose a real path.\n     */\n    private static boolean moveNear(ServerLevel level, FrontierWorkerEntity worker, BlockPos target, double speed) {\n        int[] dyOrder = {0, 1, -1, 2, -2, 3, -3};\n        for (int radius = 1; radius <= 3; radius++) {\n            for (int dx = -radius; dx <= radius; dx++) {\n                for (int dz = -radius; dz <= radius; dz++) {\n                    if (Math.max(Math.abs(dx), Math.abs(dz)) != radius) continue;\n                    for (int dy : dyOrder) {\n                        BlockPos approach = target.offset(dx, dy, dz);\n                        if (!isWalkableApproach(level, approach)) continue;\n                        if (worker.distanceToSqr(approach.getX() + 0.5D, approach.getY(), approach.getZ() + 0.5D) <= 1.0D) {\n                            worker.getNavigation().stop();\n                            return true;\n                        }\n                        if (worker.getNavigation().moveTo(approach.getX() + 0.5D, approach.getY(), approach.getZ() + 0.5D, speed)) {\n                            return true;\n                        }\n                    }\n                }\n            }\n        }\n        worker.getNavigation().stop();\n        return false;\n    }\n\n    private static boolean isWalkableApproach(ServerLevel level, BlockPos pos) {\n        if (!level.hasChunkAt(pos) || !level.hasChunkAt(pos.above()) || !level.hasChunkAt(pos.below())) return false;\n        BlockState feet = level.getBlockState(pos);\n        BlockState head = level.getBlockState(pos.above());\n        BlockState below = level.getBlockState(pos.below());\n        if (level.getBlockEntity(pos) != null || level.getBlockEntity(pos.above()) != null) return false;\n        if (!feet.getFluidState().isEmpty() || !head.getFluidState().isEmpty() || !below.getFluidState().isEmpty()) return false;\n        if ((!feet.isAir() && !feet.canBeReplaced()) || (!head.isAir() && !head.canBeReplaced())) return false;\n        return !below.isAir() && !below.canBeReplaced();\n    }''',
    'walkable interaction movement helper')
if 'move(worker,' in worker:
    raise SystemExit('legacy solid-target move helper call remains')
write(worker_path, worker)

# Construction completion must not depend on a crate/scaffold cleanup after the blueprint is physically complete.
construction_path = JAVA / 'settlement/SettlementConstructionService.java'
construction = read(construction_path)
construction = replace_once(construction, 'builder.setInvulnerable(true);\n        SettlementService.broadcast(server, data);',
                            'builder.setInvulnerable(false);\n        SettlementService.broadcast(server, data);',
                            'builder start damageability')
construction = replace_once(construction, 'if (builder.isNoAi()) builder.setNoAi(false);\n        builder.setInvulnerable(true);',
                            'if (builder.isNoAi()) builder.setNoAi(false);\n        builder.setInvulnerable(false);',
                            'builder tick damageability')
old_tick = '''        List<BuildingBlueprints.Placement> plan = RotatedBlueprints.create(type, construction.origin(), construction.rotation());\n        BlockPos supply = supplyPosition(construction.origin(), type, construction.buildingRotation());\n        Container crate = ensureSupplyCrate(level, supply);\n        if (crate == null) return false;\n        ensureConstructionScaffolds(level, data, type, supply);\n        construction = data.construction();\n        int buildStep = construction.buildStep();\n\n        if (buildStep >= plan.size()) return finishIfValid(server, data, type, plan, builder, crate, supply);'''
new_tick = '''        List<BuildingBlueprints.Placement> plan = RotatedBlueprints.create(type, construction.origin(), construction.rotation());\n        BlockPos supply = supplyPosition(construction.origin(), type, construction.buildingRotation());\n        construction = data.construction();\n        int buildStep = construction.buildStep();\n\n        // Once every blueprint step is consumed, completion no longer requires a recreated/accessible\n        // site crate or repaired scaffold. Those are cleanup details, not construction authority.\n        if (buildStep >= plan.size()) return finishIfValid(server, data, type, plan, builder, supply);\n\n        Container crate = ensureSupplyCrate(level, supply);\n        if (crate == null) return false;\n        ensureConstructionScaffolds(level, data, type, supply);'''
construction = replace_once(construction, old_tick, new_tick, 'completion-before-crate gate')
construction = construction.replace('finishIfValid(server, data, type, plan, builder, crate, supply)',
                                    'finishIfValid(server, data, type, plan, builder, supply)')
old_finish = '''    private static boolean finishIfValid(MinecraftServer server, SettlementData data, BuildingType type,\n                                         List<BuildingBlueprints.Placement> plan, FrontierWorkerEntity builder,\n                                         Container crate, BlockPos supply) {\n        ServerLevel level = server.overworld();\n        for (BuildingBlueprints.Placement placement : plan) {\n            if (!level.hasChunkAt(placement.pos())) return false;\n            BlockState current = level.getBlockState(placement.pos());\n            if (current.is(placement.state().getBlock())) continue;\n            if (!current.isAir()) {\n                builder.getNavigation().stop();\n                return false;\n            }\n            if (server.getTickCount() % BUILD_INTERVAL_TICKS != 0) return false;\n            if (!moveBuilderToWorkPosition(level, data.construction(), type, placement, builder, supply)) return false;\n            if (!level.setBlock(placement.pos(), placement.state(), NORMAL_BLOCK_UPDATE)) return false;\n            builder.swing(InteractionHand.MAIN_HAND);\n            return false;\n        }\n\n        // A valid, physically finished structure owns completion. Alpha.86 incorrectly made the\n        // builder's return walk part of the commit condition, so one failed path could hold 99% forever.\n        consolidateCompletionCargo(builder, crate, supply);\n        boolean keepPhysicalLeftovers = !crateIsEmpty(crate) || !builder.getMainHandItem().isEmpty();\n        if (!removeConstructionScaffolds(level, data.construction(), type, supply)) return false;\n        if (!keepPhysicalLeftovers && level.getBlockState(supply).is(Blocks.BARREL)\n                && !level.setBlock(supply, Blocks.AIR.defaultBlockState(), DIRECT_BLOCK_UPDATE)) return false;\n\n        data.completeConstruction(type);\n        builder.setInvulnerable(false);\n        builder.setCustomName(Component.literal(BUILDER_NAME));\n\n        // Best-effort physical return only. It can no longer block completion; no teleport/force-load.\n        returnBuilderHome(level, data, builder);\n        SettlementService.refreshResources(server, data);\n        SettlementService.broadcast(server, data);\n        return true;\n    }'''
new_finish = '''    private static boolean finishIfValid(MinecraftServer server, SettlementData data, BuildingType type,\n                                         List<BuildingBlueprints.Placement> plan, FrontierWorkerEntity builder,\n                                         BlockPos supply) {\n        ServerLevel level = server.overworld();\n        for (BuildingBlueprints.Placement placement : plan) {\n            if (!level.hasChunkAt(placement.pos())) return false;\n            BlockState current = level.getBlockState(placement.pos());\n            if (current.is(placement.state().getBlock())) continue;\n            if (!current.isAir()) {\n                builder.getNavigation().stop();\n                return false;\n            }\n            if (server.getTickCount() % BUILD_INTERVAL_TICKS != 0) return false;\n            if (!moveBuilderToWorkPosition(level, data.construction(), type, placement, builder, supply)) return false;\n            if (!level.setBlock(placement.pos(), placement.state(), NORMAL_BLOCK_UPDATE)) return false;\n            builder.swing(InteractionHand.MAIN_HAND);\n            return false;\n        }\n\n        // The valid physical blueprint is the commit boundary. Cargo consolidation, temporary scaffold\n        // cleanup, an empty site barrel, and the builder's return walk are explicitly best-effort after\n        // the settlement record commits, so none can leave a real finished building stuck at 100%.\n        ConstructionState finished = data.construction();\n        Container crate = level.getBlockEntity(supply) instanceof Container existing ? existing : null;\n        if (crate != null) consolidateCompletionCargo(builder, crate, supply);\n        boolean keepPhysicalLeftovers = (crate != null && !crateIsEmpty(crate)) || !builder.getMainHandItem().isEmpty();\n\n        data.completeConstruction(type);\n        builder.setInvulnerable(false);\n        builder.setNoAi(false);\n        builder.setCustomName(Component.literal(BUILDER_NAME));\n\n        removeConstructionScaffoldsBestEffort(level, finished, type, supply);\n        if (!keepPhysicalLeftovers && crate != null && level.getBlockState(supply).is(Blocks.BARREL)) {\n            level.setBlock(supply, Blocks.AIR.defaultBlockState(), DIRECT_BLOCK_UPDATE);\n        }\n\n        returnBuilderHome(level, data, builder);\n        SettlementService.refreshResources(server, data);\n        SettlementService.broadcast(server, data);\n        return true;\n    }'''
construction = replace_once(construction, old_finish, new_finish, 'completion-first finalizer')
insert_after = '''    private static boolean removeConstructionScaffolds(ServerLevel level, ConstructionState construction,\n                                                       BuildingType type, BlockPos supply) {\n        List<ScaffoldTower> towers = scaffoldTowers(construction.origin(), type, construction.buildingRotation(), supply);\n        for (int towerIndex = 0; towerIndex < towers.size(); towerIndex++) {\n            if (!construction.ownsScaffold(towerIndex)) continue;\n            List<ScaffoldPiece> pieces = towers.get(towerIndex).pieces();\n            for (int i = pieces.size() - 1; i >= 0; i--) {\n                ScaffoldPiece piece = pieces.get(i);\n                if (!level.hasChunkAt(piece.pos())) return false;\n                if (level.getBlockState(piece.pos()).is(piece.state().getBlock())\n                        && !level.setBlock(piece.pos(), Blocks.AIR.defaultBlockState(), DIRECT_BLOCK_UPDATE)) return false;\n            }\n        }\n        return true;\n    }'''
addition = insert_after + '''\n\n    private static void removeConstructionScaffoldsBestEffort(ServerLevel level, ConstructionState construction,\n                                                              BuildingType type, BlockPos supply) {\n        List<ScaffoldTower> towers = scaffoldTowers(construction.origin(), type, construction.buildingRotation(), supply);\n        for (int towerIndex = 0; towerIndex < towers.size(); towerIndex++) {\n            if (!construction.ownsScaffold(towerIndex)) continue;\n            List<ScaffoldPiece> pieces = towers.get(towerIndex).pieces();\n            for (int i = pieces.size() - 1; i >= 0; i--) {\n                ScaffoldPiece piece = pieces.get(i);\n                if (!level.hasChunkAt(piece.pos())) continue;\n                if (level.getBlockState(piece.pos()).is(piece.state().getBlock())) {\n                    level.setBlock(piece.pos(), Blocks.AIR.defaultBlockState(), DIRECT_BLOCK_UPDATE);\n                }\n            }\n        }\n    }'''
construction = replace_once(construction, insert_after, addition, 'best-effort scaffold cleanup')
write(construction_path, construction)

# Companion lock: same binaries, Frontier target only.
lock_path = ROOT / 'COMPANION_LOCK.json'
lock = json.loads(read(lock_path))
lock['generated_at'] = '2026-08-30'
lock.setdefault('target', {})['frontier_settlement'] = '0.1.0-alpha.88'
notes = lock.setdefault('notes', [])
note = ('Alpha.88 keeps every Alpha.87 companion binary pin unchanged. It fixes Frontier-owned worker runtime navigation by '
        'routing physical jobs to nearby loaded walkable interaction positions, keeps ordinary workers damageable, and commits '
        'a structurally complete building before any best-effort scaffold/barrel/return cleanup; no companion code/assets are copied.')
if note not in notes:
    notes.append(note)
write(lock_path, json.dumps(lock, ensure_ascii=False, indent=2) + '\n')

# Alpha.88 docs.
write(ROOT / 'WORKER_RUNTIME_RECOVERY_ALPHA88.md', '''# Frontier Settlement Alpha.88 — worker runtime recovery\n\nVersion: `0.1.0-alpha.88`\n\nAlpha.88 is a save-compatible runtime correction over Alpha.87 and adds no required settlement SavedData field.\n\n## Production movement\n- Frontier workers remain `PathfinderMob` entities with no villager profession, trade, POI, Brain, bed/jobsite, or schedule authority.\n- Work services no longer send ground navigation to the solid log, quarry block, barrel, or fenced work-center itself.\n- Each physical move order searches only loaded nearby cells around the interaction target and uses a standable feet/head position with solid dry footing.\n- There is no worker teleport and no resource chunk force-load.\n- Ordinary resource workers are normalized to `NoAI=false` and `invulnerable=false` on their work tick, repairing stale runtime flags from earlier playtest saves.\n- Resource-worker lookup uses the same 56-block local route envelope as Alpha.87 search, so a lumber worker walking toward a tree up to 48 blocks from the camp does not fall out of assignment lookup halfway through the trip.\n\n## 100% completion recovery\nAlpha.87 removed the builder-return gate, but finalization still asked for a usable site crate and successful temporary-scaffold cleanup before committing the building record. Those cleanup details could still leave a physically finished structure active at 100%.\n\nAlpha.88 makes the validated physical blueprint the actual commit boundary. The settlement building record commits and the active builder becomes damageable before scaffold cleanup, empty-barrel removal, or return-home navigation. Cleanup then runs best-effort on loaded blocks only. Real leftover cargo remains in the site barrel or builder hand.\n\nA pre-existing Alpha.87 save stuck at 100% should complete after the finished site is loaded and validates.\n\n## Update boundary\nSame-world update: fully close Minecraft, back up the world, replace/install Alpha.88, and reopen the same save. This is not a JVM hot reload.\n''')

# Cumulative source audit, replaying Alpha.87 from its exact verified candidate.
write(ROOT / 'tools/test_alpha88_source.py', '''#!/usr/bin/env python3\nimport json\nimport subprocess\nfrom pathlib import Path\nROOT = Path(__file__).resolve().parents[1]\nREPO = ROOT.parents[1]\nJAVA = ROOT / "src/main/java/kr/moonseungjun/frontiersettlement"\nA87 = ROOT / "tools/test_alpha87_source.py"\nALPHA87_SHA = "c03ac0a739735a4e3bce0053f7817635421dd12e"\nLEGACY_FILES = {\n    "projects/frontier-settlement/gradle.properties",\n    "projects/frontier-settlement/COMPANION_LOCK.json",\n    "projects/frontier-settlement/src/main/java/kr/moonseungjun/frontiersettlement/settlement/SettlementWorkerService.java",\n    "projects/frontier-settlement/src/main/java/kr/moonseungjun/frontiersettlement/settlement/SettlementConstructionService.java",\n}\n_real_read = Path.read_text\ndef alpha87_read(self, *args, **kwargs):\n    try: rel = self.resolve().relative_to(REPO.resolve()).as_posix()\n    except ValueError: rel = ""\n    if rel in LEGACY_FILES:\n        return subprocess.check_output(["git", "show", f"{ALPHA87_SHA}:{rel}"], cwd=REPO, text=True, encoding="utf-8")\n    return _real_read(self, *args, **kwargs)\nPath.read_text = alpha87_read\ntry:\n    chain = _real_read(A87, encoding="utf-8").replace('print("Frontier Settlement alpha.23-87 cumulative source audit: PASS")', 'pass')\n    ns = {"__file__": str(A87), "__name__": "__main__"}\n    exec(compile(chain, str(A87), "exec"), ns, ns)\nfinally: Path.read_text = _real_read\ndef text(path): return Path(path).read_text(encoding="utf-8")\ndef must(src, tokens, label):\n    for token in tokens:\n        if token not in src: raise SystemExit(f"{label} missing: {token}")\ndef forbid(src, tokens, label):\n    for token in tokens:\n        if token in src: raise SystemExit(f"{label} forbidden: {token}")\nprops = text(ROOT / "gradle.properties")\nworker = text(JAVA / "settlement/SettlementWorkerService.java")\nconstruction = text(JAVA / "settlement/SettlementConstructionService.java")\nlock = json.loads(text(ROOT / "COMPANION_LOCK.json"))\nmust(props, ("mod_version=0.1.0-alpha.88", "Alpha.88 worker runtime recovery"), "alpha.88 props")\nmust(worker, ("worker.setNoAi(false);", "worker.setInvulnerable(false);", "workerRouteBounds(data, building.workCenter(), LOCAL_RESOURCE_ROUTE_MARGIN)", "moveNear(level, worker, target, 0.92D)", "moveNear(level, worker, target, 0.90D)", "moveNear(level, worker, target, 0.85D)", "private static boolean moveNear", "private static boolean isWalkableApproach"), "alpha.88 worker movement")\nforbid(worker, ("move(worker,", "teleportTo(", "setChunkForced", "forceChunk"), "alpha.88 worker shortcuts")\nif construction.count("builder.setInvulnerable(false);") < 3: raise SystemExit("alpha.88 builder must be damageable at start/tick/completion")\nmust(construction, ("completion no longer requires a recreated/accessible", "finishIfValid(server, data, type, plan, builder, supply)", "ConstructionState finished = data.construction();", "data.completeConstruction(type);", "removeConstructionScaffoldsBestEffort(level, finished, type, supply);"), "alpha.88 completion")\nif construction.index("data.completeConstruction(type);") > construction.index("removeConstructionScaffoldsBestEffort(level, finished, type, supply);"):\n    raise SystemExit("alpha.88 cleanup still precedes completion commit")\nforbid(construction, ("finishIfValid(server, data, type, plan, builder, crate, supply)",), "alpha.88 crate completion gate")\nif lock.get("target", {}).get("frontier_settlement") != "0.1.0-alpha.88": raise SystemExit("alpha.88 lock mismatch")\nif not any("Alpha.88 keeps every Alpha.87 companion binary pin unchanged" in n for n in lock.get("notes", [])): raise SystemExit("alpha.88 lock rationale missing")\nprint("Frontier Settlement alpha.23-88 cumulative source audit: PASS")\n''')

write(ROOT / 'tools/test_alpha88_docs.py', '''#!/usr/bin/env python3\nimport json\nimport subprocess\nfrom pathlib import Path\nROOT = Path(__file__).resolve().parents[1]\nREPO = ROOT.parents[1]\nA87 = ROOT / "tools/test_alpha87_docs.py"\nALPHA87_SHA = "c03ac0a739735a4e3bce0053f7817635421dd12e"\n_real_read = Path.read_text\ndef alpha87_read(self, *args, **kwargs):\n    try: rel = self.resolve().relative_to(REPO.resolve()).as_posix()\n    except ValueError: rel = ""\n    if rel in {"projects/frontier-settlement/gradle.properties", "projects/frontier-settlement/COMPANION_LOCK.json"}:\n        return subprocess.check_output(["git", "show", f"{ALPHA87_SHA}:{rel}"], cwd=REPO, text=True, encoding="utf-8")\n    return _real_read(self, *args, **kwargs)\nPath.read_text = alpha87_read\ntry:\n    chain = _real_read(A87, encoding="utf-8").replace('print("Frontier Settlement alpha.87 canonical docs audit: PASS")', 'pass')\n    ns = {"__file__": str(A87), "__name__": "__main__"}\n    exec(compile(chain, str(A87), "exec"), ns, ns)\nfinally: Path.read_text = _real_read\nnote = (ROOT / "WORKER_RUNTIME_RECOVERY_ALPHA88.md").read_text(encoding="utf-8")\nprops = (ROOT / "gradle.properties").read_text(encoding="utf-8")\nlock = json.loads((ROOT / "COMPANION_LOCK.json").read_text(encoding="utf-8"))\nfor token in ("0.1.0-alpha.88", "PathfinderMob", "solid log", "standable", "invulnerable=false", "56-block", "100%", "commit boundary", "best-effort", "Same-world update"):\n    if token not in note: raise SystemExit(f"alpha.88 note missing: {token}")\nif "mod_version=0.1.0-alpha.88" not in props: raise SystemExit("alpha.88 version missing")\nif lock.get("target", {}).get("frontier_settlement") != "0.1.0-alpha.88": raise SystemExit("alpha.88 lock mismatch")\nprint("Frontier Settlement alpha.88 canonical docs audit: PASS")\n''')

print('Applied Frontier Settlement Alpha.88 worker runtime recovery patch')
